test_text_edits.new:
sites = _string_constants(tree, owners, ("BEGIN",))
# The BEGIN verb is carried by llm_kit.storage.transaction; the ledger names it
# by calling write_transaction (BEGIN IMMEDIATE) or read_transaction (plain BEGIN).
sites += [
    (owners.get(id(call), "<module>"),
     "BEGIN IMMEDIATE" if call.func.attr == "write_transaction" else "BEGIN")
    for call in ast.walk(tree)
    if isinstance(call, ast.Call) and isinstance(call.func, ast.Attribute)
    and call.func.attr in ("write_transaction", "read_transaction")
]
